	private void assertReentrantClose(RuntimeException callbackFailure, RuntimeException sourceFailure,
			RuntimeException semanticFailure) {
		var memory = SealedBoundaryTestSupport.source(List.of());
		var strategy = SealedBoundaryTestSupport.nativeStrategy(memory, true);
		var context = new QueryEvaluationContext.Minimal(null);
		var row = new QueryBindingSet();
		row.setBinding("k", memory.getValueFactory().createLiteral("a"));
		var assignment = new BindingSetAssignment();
		assignment.setBindingSets(List.of(row));
		QueryEvaluationStep logical = SealedBoundaryTestSupport.ordinary(memory, true).precompile(assignment, context);
		AtomicInteger semanticCloses = new AtomicInteger();
		AtomicInteger sourceCloses = new AtomicInteger();
		AtomicReference<NativeExecutionContext> actualOwner = new AtomicReference<>();
		AtomicReference<CloseableIteration<BindingSet>> ordered = new AtomicReference<>();
		QueryEvaluationStep source = bindings -> {
			SyntheticValueSource evaluation = SyntheticValueSource.forInvocation(memory,
					strategy.getQueryExecutionPolicy(), bindings);
			NativeExecutionContext owner = evaluation.executionContext();
			owner.nativeState(new Object(), () -> (AutoCloseable) () -> {
				semanticCloses.incrementAndGet();
				if (semanticFailure != null) {
					throw semanticFailure;
				}
			});
			actualOwner.set(owner);
			class Input
					implements CloseableIteration<BindingSet>, CooperativeCancellation, NativeExecutionContextCarrier {
				private final CloseableIteration<BindingSet> delegate = logical.evaluate(bindings);
				private boolean closed;

				@Override
				public boolean hasNext() {
					return !closed && delegate.hasNext();
				}

				@Override
				public BindingSet next() {
					return delegate.next();
				}

				@Override
				public void remove() {
					throw new UnsupportedOperationException();
				}

				@Override
				public NativeExecutionContext executionContext() {
					return owner;
				}

				@Override
				public boolean requestCancellation() {
					if (callbackFailure != null) {
						throw callbackFailure;
					}
					ordered.get().close();
					assertFalse(owner.isClosed(), "the admitted source callback still owns its actual execution");
					assertEquals(0, semanticCloses.get(), "semantic resources outlive the admitted callback");
					return false;
				}

				@Override
				public void close() {
					if (!closed) {
						closed = true;
						sourceCloses.incrementAndGet();
						try {
							delegate.close();
						} finally {
							owner.close();
							if (sourceFailure != null) {
								throw sourceFailure;
							}
						}
					}
				}
			}
			return new Input();
		};
		Order order = new Order(assignment, new OrderElem(Var.of("k")));
		QueryEvaluationStep step = NativeRootPipeline.order(source, order, strategy, context);
		assertNotNull(step);
		try (var result = step.evaluate(EmptyBindingSet.getInstance())) {
			ordered.set(result);
			if (callbackFailure == null) {
				assertTrue(((CooperativeCancellation) result).requestCancellation(),
						"ORDER accepts its own live request");
			} else {
				RuntimeException actual = assertThrows(RuntimeException.class, () -> {
					// The callback's primary exists before the actual Java caller closes the result.
					try (result) {
						((CooperativeCancellation) result).requestCancellation();
					}
				});
				assertSame(callbackFailure, actual);
				assertTrue(contains(actual, sourceFailure), "source cleanup identity remains reachable");
				assertTrue(contains(actual, semanticFailure), "semantic cleanup identity remains reachable");
			}
			assertFalse(result.hasNext(), "reentrant close wins before any ordered row is published");
		}
		assertTrue(actualOwner.get().isClosed(), "the actual source owner retires after the callback exits");
		assertEquals(1, sourceCloses.get());
		assertEquals(1, semanticCloses.get());
	}

